// rule [4] verbatim decode (no rstrip, no ascii guard)
function theirDec(s){let z=0;while(z<s.length&&s[z]==='1')z++;let n=0n;for(const ch of s){const i=A.indexOf(ch);if(i<0)throw new Error('Invalid character '+ch);n=n*58n+BigInt(i);}const by=[];while(n>0n){by.unshift(Number(n%256n));n=n/256n;}return Buffer.concat([Buffer.alloc(z,0),Buffer.from(by)]);}
function theirEnc(buf){let z=0;while(z<buf.length&&buf[z]===0)z++;let n=0n;for(const b of buf)n=n*256n+BigInt(b);let o='';while(n>0n){o=A[Number(n%58n)]+o;n=n/58n;}return '1'.repeat(z)+o;}
const theirEncck=p=>theirEnc(Buffer.concat([p,m.ck(p)]));
const theirDecck=s=>{const f=theirDec(s);const p=f.subarray(0,f.length-4);if(!f.subarray(f.length-4).equals(m.ck(p)))throw new Error('Invalid checksum');return p;};

function run(c,b){
  try{
    const out=execFileSync(E,['--a','T','--b',b,'--c',c,'--d','y','--e','3','--f','1','--g','2'],{encoding:'latin1',stdio:['ignore','pipe','pipe']});
    const L=out.split('\n');
    return {rc:0,L3:L[2],L4:L[3],L10:L[9],L11:L[10]};
  }catch(e){ return {rc:e.status, err:(e.stderr||'').toString().split('\n').filter(x=>/Error|error/.test(x)).slice(-1)[0]||''}; }
}
function mine(c,b){
  try{
    const e1=m.encck(Buffer.from(c,'utf8')), d1=m.decck(e1);
    const dd=m.decStr(b), e2=m.encck(dd), d2=m.decck(e2);
    return {rc:0,L3:m.pyrepr(e1),L4:m.pyrepr(d1),L10:m.pyrepr(e2),L11:m.pyrepr(d2)};
  }catch(e){ return {rc:1,err:e.message}; }
}
function theirs(c,b){
  try{
    const e1=Buffer.from(theirEncck(Buffer.from(c,'utf8')),'ascii'), d1=theirDecck(e1.toString('ascii'));
    const dd=theirDec(b), e2=Buffer.from(theirEncck(dd),'ascii'), d2=theirDecck(e2.toString('ascii'));
    return {rc:0,L3:m.pyrepr(e1),L4:m.pyrepr(d1),L10:m.pyrepr(e2),L11:m.pyrepr(d2)};
  }catch(e){ return {rc:1,err:e.message}; }
